Register-ArgumentCompleter -Native -CommandName nvme -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $tokens = $commandAst.CommandElements | ForEach-Object { $_.ToString() }

    # Determine which tokens are fully entered (exclude the word being typed).
    if ($tokens.Count -le 1) {
        $completed = @()
    } elseif ($wordToComplete -ne '') {
        if ($tokens.Count -eq 2) {
            $completed = @()
        } else {
            $completed = $tokens[1..($tokens.Count-2)]
        }
    } else {
        $completed = $tokens[1..($tokens.Count-1)]
    }

    $nonOpt = @($completed | Where-Object { $_ -notlike '-*' })

    # Completing the top-level command/plugin name.
    if ($nonOpt.Count -eq 0) {
        return $script:NvmeCommands | Where-Object { $_ -like "$wordToComplete*" } |
            ForEach-Object { [System.Management.Automation.CompletionResult]::new("$_ ", $_, 'ParameterValue', $_) }
    }

    $first = $nonOpt[0]

    # 'help CMD' takes one command argument; 'version' takes nothing.
    if ($first -eq 'help') {
        if ($nonOpt.Count -eq 1) {
            return $script:NvmeCommands | Where-Object { $_ -like "$wordToComplete*" } |
                ForEach-Object { [System.Management.Automation.CompletionResult]::new("$_ ", $_, 'ParameterValue', $_) }
        }
        return
    }
    if ($first -eq 'version') { return }

    $key = $null
    if ($script:NvmePluginCommands.ContainsKey($first)) {
        if ($nonOpt.Count -eq 1) {
            return $script:NvmePluginCommands[$first] | Where-Object { $_ -like "$wordToComplete*" } |
                ForEach-Object { [System.Management.Automation.CompletionResult]::new("$_ ", $_, 'ParameterValue', $_) }
        }
        $key = "$first $($nonOpt[1])"
    } else {
        $key = $first
    }

    # Check if we are completing the value of an option (previous token is an
    # option that takes values or a file path).
    if ($null -ne $key -and $completed.Count -gt 0) {
        $prevToken = $completed[-1]
        if ($prevToken -like '-*') {
            $valKey = "$key $prevToken"
            if ($script:NvmeOptionValues.ContainsKey($valKey)) {
                return $script:NvmeOptionValues[$valKey] |
                    Where-Object { $_ -like "$wordToComplete*" } |
                    ForEach-Object { [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_) }
            }
            if ($script:NvmeFileOptions.ContainsKey($valKey)) {
                return Get-ChildItem -Path "$wordToComplete*" -ErrorAction SilentlyContinue |
                    ForEach-Object {
                        $text = if ($_.FullName -match '[ ''`]') { "'$($_.FullName -replace "'", "''")'"}
                                else { $_.FullName }
                        $type = if ($_.PSIsContainer) { 'ProviderContainer' } else { 'ProviderItem' }
                        [System.Management.Automation.CompletionResult]::new($text, $_.Name, $type, $text)
                    }
            }
        }
    }

    # Handle --option=value completion (attached form; short opts don't use =).
    if ($null -ne $key -and $wordToComplete -match '^(--[^=]+=)(.*)$') {
        $optPart = $Matches[1] -replace '=$',''
        $valPrefix = $Matches[2]
        $valKey = "$key $optPart"
        if ($script:NvmeOptionValues.ContainsKey($valKey)) {
            return $script:NvmeOptionValues[$valKey] |
                Where-Object { $_ -like "$valPrefix*" } |
                ForEach-Object { [System.Management.Automation.CompletionResult]::new("$optPart=$_", $_, 'ParameterValue', $_) }
        }
        if ($script:NvmeFileOptions.ContainsKey($valKey)) {
            return Get-ChildItem -Path "$valPrefix*" -ErrorAction SilentlyContinue |
                ForEach-Object {
                    $path = if ($_.FullName -match '[ ''`]') { "'$($_.FullName -replace "'", "''")'"}
                            else { $_.FullName }
                    $text = "$optPart=$path"
                    $type = if ($_.PSIsContainer) { 'ProviderContainer' } else { 'ProviderItem' }
                    [System.Management.Automation.CompletionResult]::new($text, $_.Name, $type, $text)
                }
        }
    }

    if ($null -ne $key -and $script:NvmeOptions.ContainsKey($key)) {
        $results = @($script:NvmeOptions[$key] | Where-Object { $_ -like "$wordToComplete*" } |
            ForEach-Object { [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterName', $_) })
        # Offer a device-path hint for commands that take a device argument
        # (help/version are handled above).
        if ('/dev/nvme' -like "$wordToComplete*" -and
            -not $script:NvmeNoDevice.ContainsKey($key)) {
            $results += [System.Management.Automation.CompletionResult]::new(
                '/dev/nvme', '/dev/nvme', 'ParameterValue', 'NVMe device (e.g. /dev/nvme0, /dev/nvme0n1)')
        }
        return $results
    }
}
